await (async (page) => {
  // Check if there's a click handler issue
  const result = await page.evaluate(() => {
    const btn = Array.from(document.querySelectorAll('button')).find(b => b.textContent.includes('确认清空'));
    if (!btn) return { error: 'no button' };
    // Check for event listeners via getEventListeners (only in devtools, not available)
    // Instead, check if button is covered by another element
    const rect = btn.getBoundingClientRect();
    const el = document.elementFromPoint(rect.x + rect.width/2, rect.y + rect.height/2);
    return {
      btnRect: {x: rect.x, y: rect.y, w: rect.width, h: rect.height},
      topElement: el ? el.tagName + '.' + el.className + ' text=' + (el.textContent||'').slice(0,30) : null,
      isBtn: el === btn
    };
  });
  return result;
})(page);
